// GENERATED by scripts/export-mod-physics.mjs from the ProTanki server's
// garage data — do not edit by hand. Per-modification physics exactly as the
// original server handed them to the client (BattleTank.kt): hull speed (m/s),
// turn speed (rad/s), the four acceleration terms (m/s^2, rad/s^2), suspension
// damping and mass; weapon turret speed (rad/s) and acceleration (rad/s^2),
// and the impact/kickback COEFFICIENTS the client multiplied by
// WeaponConst.BASE_IMPACT_FORCE (WeaponCommonModel.as:48).
//
// Coverage: every hull has all four modifications. Weapons are patchy in the
// dump — Shaft, Firebird and Freeze have no physics block at all, Isida,
// Thunder and Twins none for M0 — so consumers fall back where an entry is
// missing.

export interface HullPhysics {
  speed: number;
  turnSpeed: number;
  acceleration: number;
  reverseAcceleration: number;
  sideAcceleration: number;
  turnAcceleration: number;
  reverseTurnAcceleration: number;
  damping: number;
  mass: number;
}

export interface WeaponPhysics {
  turretRotationSpeed: number;
  turretTurnAcceleration: number;
  impactForce: number;
  kickback: number;
}

/** WeaponConst.BASE_IMPACT_FORCE: the impact/kickback coefficients are multiplied by this. */
export const BASE_IMPACT_FORCE = 5000000;

